#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_append_n_resize_failure(void) {
    // Setup: create a buffer with small content and size
    buffer_t *buf = helper_create_buffer_with_content("abc");
    TEST_ASSERT_NOT_NULL(buf);

    // The buffer's initial content is "abc", length 3
    // We want to append 5 more characters, so needed = 3 + 5 = 8
    // To trigger the resize path, ensure buf->len <= 8
    // (helper_create_buffer_with_content should allocate just enough for "abc")
    // Now, simulate buffer_resize failure by making buffer_resize return -1
    // This is done by failing the next allocation after the 2 setup allocations

    // Count: helper_create_buffer_with_content("abc") calls buffer_new_with_copy, which calls buffer_new_with_size
    // That is 2 allocations (struct + data)
    // buffer_append_n will call buffer_resize, which calls realloc (1 more allocation)
    // To fail the realloc, we need to fail after 2 allocations
    #include "malloc_wrap.h"
    malloc_fail_after(2);

    // Prepare string to append (does not need to be null-terminated)
    const char *to_append = "12345";
    size_t append_len = 5;

    int ret = buffer_append_n(buf, to_append, append_len);

    // Should return -1 due to resize failure
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // Buffer content and length should remain unchanged
    helper_assert_buffer_content(buf, "abc");
    helper_assert_buffer_length(buf, 3);

    // Cleanup
    buffer_free(buf);
    malloc_reset();
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_n_resize_failure);
    return UNITY_END();
}

